/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadCinzel = makeLoadFont('Cinzel');
const loadLora = makeLoadFont('Lora');

// Module-level font loading ensures fonts are ready before frame 0
const { fontFamily: cinzelFamily } = loadCinzel();
const { fontFamily: loraFamily } = loadLora();



export type BookAnimationProps = Record<string, any>;

const BookAnimation: React.FC<BookAnimationProps> = ({
  backgroundColor = "#141a16",
  transparentBackground = false,
  durationInSeconds = 12,
  bookColor = "#21472e",
  title = "The Catechism of the Catholic Church",
  articleHeader = "Article 847",
  articleText = "Those who, through no fault of their own, do not know the Gospel of Christ or his Church, but who nevertheless seek God with a sincere heart, and, moved by grace, try in their actions to do his will as they know it through the dictates of their conscience—those too may achieve eternal salvation.",
  highlightColor = "rgba(250, 219, 95, 0.75)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? undefined : backgroundColor;

  // Book Dimensions - Optimized for 9:16 (Portrait)
  const bW = width * 0.44; // e.g., 475px at 1080p
  const bH = bW * 1.5; // e.g., 712px at 1080p

  // Timeline Setup
  const durationFrames = durationInSeconds * fps;
  const openStart = 15;
  const openDuration = 45;
  const openEnd = openStart + openDuration;

  const zoomStart = openEnd + 15;
  const zoomDuration = 45;
  const zoomEnd = zoomStart + zoomDuration;

  // Highlight begins while zoom is settling
  const highlightStart = zoomStart + Math.floor(zoomDuration * 0.5);
  const highlightEnd = durationFrames - 30; // Hold at the end
  const highlightDuration = Math.max(1, highlightEnd - highlightStart);

  // Opening Animation Progress
  const openProgress = interpolate(frame, [openStart, openEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  
  // Rotating the left page over the spine
  const coverRotation = interpolate(openProgress, [0, 1], [0, -180]);
  
  // Shifting the book from center-aligned cover to center-aligned spread
  const openingShift = interpolate(openProgress, [0, 1], [-bW / 2, 0]);

  // Zoom Animation Progress
  const zoomProgress = interpolate(frame, [zoomStart, zoomEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  
  // Zooming into the center of the right page (scaled up to fill 9:16 screen)
  const zoomScale = interpolate(zoomProgress, [0, 1], [1, 2.1]);
  // Shifting the focal point to the center of the screen
  const zoomTranslateX = interpolate(zoomProgress, [0, 1], [0, -bW / 2]);

  // Text Data
  const words = articleText.split(" ");
  const wordsLength = words.length;
  // Dynamic wipe speed per word based on text length
  const wipeFrames = Math.max(5, (highlightDuration / Math.max(1, wordsLength)) * 1.5);
  
  // Spine crease shadow opacity
  const spineOpacity = interpolate(openProgress, [0.5, 1], [0, 1], { extrapolateLeft: "clamp" });

  // Blur target matching logic
  const phraseToBlur = "through no fault of their own, do not know the Gospel of Christ or his Church, but who nevertheless seek God with a sincere heart, and, moved by grace,";
  const phraseWords = phraseToBlur.split(" ");
  let blurStartIndex = -1;
  
  for (let i = 0; i <= words.length - phraseWords.length; i++) {
    let match = true;
    for (let j = 0; j < phraseWords.length; j++) {
      if (words[i + j] !== phraseWords[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      blurStartIndex = i;
      break;
    }
  }
  const blurEndIndex = blurStartIndex !== -1 ? blurStartIndex + phraseWords.length - 1 : -1;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        alignItems: "center",
        justifyContent: "center",
        perspective: 2500,
      }}
    >
      {/* Zoom Wrapper */}
      <div
        style={{
          transformOrigin: "75% 50%",
          transform: `translateX(${zoomTranslateX}px) scale(${zoomScale})`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: bW * 2,
          height: bH,
        }}
      >
        {/* Book Container */}
        <div
          style={{
            position: "relative",
            width: bW * 2,
            height: bH,
            transformStyle: "preserve-3d",
            transform: `translateX(${openingShift}px)`,
          }}
        >
          {/* Base Right Page */}
          <div
            style={{
              position: "absolute",
              left: bW,
              top: 0,
              width: bW,
              height: bH,
              backgroundColor: "#FAF9F6",
              boxShadow: "20px 20px 50px rgba(0,0,0,0.3), inset 20px 0 40px rgba(0,0,0,0.06)",
              borderRadius: "0 8px 8px 0",
              overflow: "hidden",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              padding: "8%",
              boxSizing: "border-box",
            }}
          >
            <h2
              style={{
                fontFamily: cinzelFamily,
                fontSize: 26,
                textAlign: "center",
                color: "#111",
                marginBottom: 24,
                transition: "none",
              }}
            >
              {articleHeader}
            </h2>
            <p
              style={{
                fontFamily: loraFamily,
                fontSize: 18,
                lineHeight: 1.6,
                color: "#222",
                textAlign: "justify",
                transition: "none",
              }}
            >
              {words.map((word, i) => {
                const wStart = highlightStart + (i / wordsLength) * highlightDuration;
                const wEnd = wStart + wipeFrames;
                
                const isBlurred = blurStartIndex !== -1 && i >= blurStartIndex && i <= blurEndIndex;

                const wordHighlightProgress = isBlurred ? 0 : interpolate(
                  frame,
                  [wStart, wEnd],
                  [0, 1],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );

                return (
                  <React.Fragment key={i}>
                    <span
                      style={{
                        display: "inline",
                        backgroundImage: isBlurred ? "none" : `linear-gradient(to right, ${highlightColor}, ${highlightColor})`,
                        backgroundSize: isBlurred ? "0% 100%" : `${wordHighlightProgress * 100}% 100%`,
                        backgroundRepeat: "no-repeat",
                        backgroundPosition: "left center",
                        padding: "0 2px",
                        margin: "0 -2px",
                        borderRadius: "2px",
                        transition: "none",
                        filter: isBlurred ? "blur(5px)" : "none",
                        opacity: isBlurred ? 0.6 : 1,
                      }}
                    >
                      {word}
                    </span>{" "}
                  </React.Fragment>
                );
              })}
            </p>
          </div>

          {/* Opening Left Page (Front Cover + Inner Cover) */}
          <div
            style={{
              position: "absolute",
              left: bW,
              top: 0,
              width: bW,
              height: bH,
              transformOrigin: "left center",
              transformStyle: "preserve-3d",
              transform: `rotateY(${coverRotation}deg)`,
              borderRadius: "0 8px 8px 0",
            }}
          >
            {/* Outer Front Cover */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backfaceVisibility: "hidden",
                backgroundColor: bookColor,
                backgroundImage: "linear-gradient(45deg, rgba(0,0,0,0.6) 0%, transparent 40%, rgba(255,255,255,0.1) 100%)",
                borderRadius: "0 8px 8px 0",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                padding: "8%",
                boxSizing: "border-box",
                borderLeft: "12px solid rgba(0,0,0,0.25)",
                boxShadow: openProgress < 0.5 
                  ? "10px 10px 30px rgba(0,0,0,0.5), inset -5px 0 10px rgba(0,0,0,0.2)" 
                  : "-20px 20px 50px rgba(0,0,0,0.3), inset -5px 0 10px rgba(0,0,0,0.2)",
              }}
            >
              <h1
                style={{
                  fontFamily: cinzelFamily,
                  fontStyle: "italic",
                  fontSize: 52,
                  textAlign: "center",
                  color: "#FFFFFF",
                  textShadow: "1px 1px 3px rgba(0,0,0,0.4)",
                  lineHeight: 1.2,
                  transition: "none",
                }}
              >
                {title}
              </h1>
            </div>

            {/* Inner Front Cover (Back of the front cover) */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                backfaceVisibility: "hidden",
                transform: "rotateY(180deg)",
                backgroundColor: "#FAF9F6",
                borderRadius: "8px 0 0 8px",
                boxShadow: "inset -20px 0 40px rgba(0,0,0,0.06)",
              }}
            />
          </div>

          {/* Center Spine Crease Effect */}
          <div
            style={{
              position: "absolute",
              left: bW - 20,
              top: 0,
              width: 40,
              height: bH,
              background: "linear-gradient(to right, transparent, rgba(0,0,0,0.12) 50%, transparent)",
              opacity: spineOpacity,
              zIndex: 10,
              pointerEvents: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BookAnimation;